INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207VGR6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for $\\$13$ each and child tickets for $\\$7$ each. On a certain evening, 153 tickets were sold for a total of $\\$1{,}503$. How many child tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$81$"},{"key":"C","text":"$62$"},{"key":"D","text":"$91$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $a$ be adult tickets and $c$ be child tickets. Then $a + c = 153$ and $13a + 7c = 1503$. Substituting $a = 153 - c$: $13(153 - c) + 7c = 1503$, giving $1989 - 13c + 7c = 1503$, so $1989 - 6c = 1503$. Then $6c = 486$ and $c = 81$. Verification: $a = 72$, revenue $= 13(72) + 7(81) = 936 + 567 = 1503$. The value $72$ is the number of adult tickets, not child tickets, resulting from answering for the wrong variable. The value $62$ comes from an arithmetic slip such as computing $486 \\div 6$ incorrectly. The value $91$ comes from an equation setup error such as swapping the ticket prices.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20QAC45', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 7x^2 - 3$. What is the value of $f(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$11$"},{"key":"C","text":"$-25$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -2$ into $f(x) = 7x^2 - 3$ gives $f(-2) = 7(-2)^2 - 3 = 7(4) - 3 = 28 - 3 = 25$. The value $11$ results from computing $7(2) - 3 = 11$, forgetting to square. The value $-25$ results from incorrectly applying the negative sign as $-(7 \\cdot 4) - 3$. The value $31$ results from computing $7(4) + 3$, using addition instead of subtraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20TXEF1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'If $4x + 7y = 53$ and $4x - 3y = 13$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Subtract the second equation from the first: $(4x + 7y) - (4x - 3y) = 53 - 13$, giving $10y = 40$, so $y = 4$. Verification: substituting $y = 4$ into the second equation gives $4x - 12 = 13$, so $4x = 25$ and $x = 6.25$. Checking the first equation: $4(6.25) + 7(4) = 25 + 28 = 53$, which confirms the solution.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2184W2E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe uses $3$ cups of rice for every $7$ cups of water. How many cups of water are needed for $15$ cups of rice?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35', ARRAY['35'], E'The ratio of rice to water is $3:7$. Setting up the proportion $\\frac{3}{7} = \\frac{15}{x}$, cross-multiplying gives $3x = 105$, so $x = 35$. Therefore, $35$ cups of water are needed.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM229F3NH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $p$ is defined by $p(x) = x^3 - 10$. What is the value of $p(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Substituting $x = 3$: $p(3) = 3^3 - 10 = 27 - 10 = 17$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Q0QDD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A mechanic charges a flat diagnostic fee plus an hourly rate for labor. For a job taking $3$ hours, the total charge is $\\$247$. For a job taking $7$ hours, the total charge is $\\$527$. What is the mechanic''s hourly rate, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$70$"},{"key":"C","text":"$75$"},{"key":"D","text":"$82$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $d$ be the diagnostic fee and $r$ the hourly rate. The system is $d + 3r = 247$ and $d + 7r = 527$. Subtracting the first equation from the second: $4r = 280$, so $r = 70$. The hourly rate is $\\$70$. A student who subtracts incorrectly, getting $4r = 260$, arrives at $r = 65$. A student who divides the larger total by its hours, $\\frac{527}{7} \\approx 75.3$, and rounds to $75$ ignores the flat fee. A student who divides the smaller total by its hours, $\\frac{247}{3} \\approx 82.3$, and rounds to $82$ also ignores the flat fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22YJ76V', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has the equation $(x - 7)^2 + (y + 4)^2 = 81$. What is the circumference of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$81\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$9\\pi$"},{"key":"D","text":"$162\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation $(x - 7)^2 + (y + 4)^2 = 81$ represents a circle with center $(7, -4)$ and $r^2 = 81$, so $r = 9$. The circumference is $C = 2\\pi r = 2\\pi(9) = 18\\pi$. The value $81\\pi$ results from using $r^2$ in place of $r$ in the circumference formula, computing $2\\pi(81)$ or confusing circumference with area $\\pi r^2$. The value $9\\pi$ uses $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The value $162\\pi$ compounds the error of using $r^2 = 81$ in place of $r$ and then doubling, computing $2 \\times 81\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23US837', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'If $2x + 3y = 29$ and $x - 3y = -14$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Add the two equations to eliminate $y$: $(2x + 3y) + (x - 3y) = 29 + (-14)$, giving $3x = 15$, so $x = 5$. To verify, substitute $x = 5$ into the second equation: $5 - 3y = -14$, so $-3y = -19$ and $y = \\frac{19}{3}$. Checking the first equation: $2(5) + 3 \\cdot \\frac{19}{3} = 10 + 19 = 29$, which confirms the solution.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24B6NWA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The quadratic function $h$ is defined by $h(x) = -3(x - 7)^2 + 48$. The function $h$ has zeros at $x = a$ and $x = b$, where $a < b$. What is the value of $b - a$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$4$"},{"key":"C","text":"$14$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $h(x) = 0$: $-3(x - 7)^2 + 48 = 0$, so $(x - 7)^2 = 16$, giving $x - 7 = \\pm 4$. Thus $x = 3$ or $x = 11$. With $a = 3$ and $b = 11$, $b - a = 8$. The value $4$ comes from finding only the positive root $x - 7 = 4$ and reporting just that distance from the vertex. The value $14$ comes from adding the zeros $3 + 11$ instead of subtracting. The value $16$ comes from reporting $(x-7)^2 = 16$ without taking the square root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24XD66G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $q$ is defined by $q(x) = -2x^2 + 12x - 7$. What is the maximum value of $q(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex x-coordinate is $x = -\\frac{12}{2(-2)} = 3$. Substituting: $q(3) = -2(9) + 12(3) - 7 = -18 + 36 - 7 = 11$. The value $3$ comes from reporting the x-coordinate of the vertex instead of the maximum output value. The value $-7$ is simply the constant term, which would be the y-intercept, not the maximum. The value $25$ results from a sign error such as computing $2(9) + 36 - 7 - 16 = 25$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM256VRGO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'In the system of equations $y = 2x + 1$ and $y = x^2 - 4x + 9$, the graphs intersect at the points $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $x_1 + x_2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Setting the equations equal: $2x + 1 = x^2 - 4x + 9$, which gives $x^2 - 6x + 8 = 0$. Factoring: $(x - 2)(x - 4) = 0$, so $x_1 = 2$ and $x_2 = 4$. Therefore $x_1 + x_2 = 6$. Alternatively, by Vieta''s formulas, the sum of the roots of $x^2 - 6x + 8 = 0$ is $6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25W13US', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $3x^2 - 17x + 10 = 0$ and $x > 2$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Using the quadratic formula: $x = \\frac{17 \\pm \\sqrt{289 - 120}}{6} = \\frac{17 \\pm \\sqrt{169}}{6} = \\frac{17 \\pm 13}{6}$. This gives $x = \\frac{30}{6} = 5$ or $x = \\frac{4}{6} = \\frac{2}{3}$. Since $x > 2$, the answer is $5$. Alternatively, factoring: $3x^2 - 17x + 10 = (3x - 2)(x - 5) = 0$, confirming $x = \\frac{2}{3}$ or $x = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26NGLNU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(5x - 3)^2 - (5x + 3)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$-60x$"},{"key":"B","text":"$-18$"},{"key":"C","text":"$50x^2 - 18$"},{"key":"D","text":"$-30x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the difference of squares identity $a^2 - b^2 = (a-b)(a+b)$ with $a = 5x - 3$ and $b = 5x + 3$: $(5x - 3 - 5x - 3)(5x - 3 + 5x + 3) = (-6)(10x) = -60x$. The value $-18$ comes from only computing the constant terms: $(-3)^2 - (3)^2 = 9 - 9 = 0$, then misapplying cross terms. The expression $50x^2 - 18$ comes from expanding each square separately but dropping the cross terms: $(25x^2 - 9) - (25x^2 + 9)$ yields $-18$, not $50x^2 - 18$, revealing the setup error. The value $-30x$ comes from computing $(-3)(10x)$ instead of $(-6)(10x)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26RNRCM', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $t$ satisfies the inequality $3t - 17 > 4$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Solve $3t - 17 > 4$: add 17 to both sides to get $3t > 21$, then divide by 3 to get $t > 7$. The only value strictly greater than 7 among the choices is $8$. The value $7$ is the boundary but does not satisfy the strict inequality since $3(7) - 17 = 4$, not greater than 4. The value $6$ is less than 7 and may result from dividing 21 by 3 incorrectly or misunderstanding the direction of the inequality. The value $5$ is well below the threshold and results from an arithmetic error such as subtracting 17 from only one side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM281KVGJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The population of a town was $12{,}500$ at the start of $2021$. The population increased by $6\\%$ during $2021$ and then decreased by $11\\%$ during $2022$. To the nearest whole number, what was the population of the town at the end of $2022$?', NULL, $lyceon_json$[{"key":"A","text":"$11{,}792$"},{"key":"B","text":"$11{,}875$"},{"key":"C","text":"$11{,}125$"},{"key":"D","text":"$10{,}458$"}]$lyceon_json$::jsonb, 'A', NULL, E'After a $6\\%$ increase in $2021$, the population is $12{,}500 \\times 1.06 = 13{,}250$. After an $11\\%$ decrease in $2022$, the population is $13{,}250 \\times 0.89 = 11{,}792.5$, which is closest to $11{,}792$ among the answer choices. The value $11{,}875$ comes from computing $12{,}500 \\times 0.95 = 11{,}875$, incorrectly treating the net change as $-5\\%$. The value $11{,}125$ results from subtracting $11\\%$ of the original $12{,}500$ (which is $1{,}375$) to get $11{,}125$, ignoring the $6\\%$ increase entirely. The value $10{,}458$ results from mistakenly applying both percentages as decreases, computing $12{,}500 \\times 0.94 \\times 0.89 = 10{,}457.5$, which rounds to $10{,}458$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM287IQQG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills $7$ bottles every $4$ minutes. At this constant rate, how many bottles will the machine fill in $54$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$87.5$"},{"key":"B","text":"$94.5$"},{"key":"C","text":"$94$"},{"key":"D","text":"$98$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{7}{4}$ bottles per minute, which equals $1.75$ bottles per minute. Multiplying by $54$ minutes gives $1.75 \\times 54 = 94.5$ bottles. The value $87.5$ results from mistakenly using $50$ minutes instead of $54$, computing $1.75 \\times 50$. The value $94$ comes from truncating the decimal rather than reporting the exact product. The value $98$ arises from rounding $\\frac{54}{4} = 13.5$ up to $14$ and then computing $14 \\times 7 = 98$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28FYLF8', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'A plumber charges a flat fee of $\\$45$ plus $\\$28$ per hour of labor. If the total charge for a job is $\\$185$, how many hours of labor did the job require?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set up the equation: $45 + 28h = 185$. Subtract $45$: $28h = 140$. Divide by $28$: $h = 5$. The value $4$ comes from dividing $140$ by $28$ incorrectly or a rounding error. The value $6$ comes from setting up $28h = 185$ without subtracting the flat fee. The value $7$ comes from dividing $185$ by $28$ without subtracting $45$ first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28LP0YE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the co-interior (same-side interior) angles measures $(4x + 11)°$, and the other co-interior angle measures $(6x - 31)°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$20$"},{"key":"C","text":"$11$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so $(4x + 11) + (6x - 31) = 180$. Combining like terms gives $10x - 20 = 180$, so $10x = 200$ and $x = 20$. The value $21$ results from incorrectly setting the angles equal (as if they were alternate interior angles): $4x + 11 = 6x - 31$ gives $2x = 42$, so $x = 21$. The value $11$ arises from treating the angles as complementary (summing to $90°$): $10x - 20 = 90$ gives $x = 11$. The value $16$ comes from a sign error when combining the constants, computing $10x + 20 = 180$ instead of $10x - 20 = 180$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4Q089', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery company charges a flat fee of $\\$23$ plus $\\$1.70$ per pound for shipping. A customer has a budget of at most $\\$84.50$ for shipping. If the customer must also pay a $\\$9$ insurance surcharge on any order exceeding 20 pounds, what is the maximum whole number of pounds the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$36$"},{"key":"C","text":"$31$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $p$ be the number of pounds. Since all answer choices exceed 20 pounds, the insurance surcharge applies. The total cost is $23 + 1.70p + 9 \\leq 84.50$, which gives $32 + 1.70p \\leq 84.50$, so $1.70p \\leq 52.50$, meaning $p \\leq 30.88$. The maximum whole number is $30$. Verification: $23 + 1.70(30) + 9 = 23 + 51 + 9 = 83 \\leq 84.50$, and $23 + 1.70(31) + 9 = 23 + 52.70 + 9 = 84.70 > 84.50$. The value $36$ results from forgetting the insurance surcharge, solving $23 + 1.70p \\leq 84.50$ to get $p \\leq 36.17$. The value $31$ comes from rounding $30.88$ up instead of down. The value $28$ comes from a computation error in the per-pound cost step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B46TNM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours studied and the score on a quiz for $12$ students. The line of best fit for the data is $y = 6.3x + 41$, where $x$ is the number of hours studied and $y$ is the predicted quiz score. What is the best interpretation of the slope $6.3$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour studied, the predicted quiz score increases by $6.3$ points."},{"key":"B","text":"A student who studies $0$ hours is predicted to score $6.3$ points on the quiz."},{"key":"C","text":"For each additional point scored on the quiz, the number of hours studied increases by $6.3$ hours."},{"key":"D","text":"The average quiz score of all $12$ students is $6.3$ points above the minimum score."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 6.3x + 41$, the slope $6.3$ represents the predicted change in $y$ (quiz score) for each one-unit increase in $x$ (hours studied). So for each additional hour studied, the predicted quiz score increases by $6.3$ points. The option stating a student who studies $0$ hours scores $6.3$ confuses slope with intercept; the $y$-intercept is $41$. The option reversing the relationship (hours per point) inverts the independent and dependent variables. The option about the average score misinterprets the slope as a comparison to a baseline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQJSK7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $400$ registered voters in a city found that $57\\%$ support a proposed park renovation. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $53\\%$ and $61\\%$ of all registered voters in the city are likely to support the park renovation."},{"key":"B","text":"Exactly $57\\%$ of all registered voters in the city support the park renovation."},{"key":"C","text":"Between $53\\%$ and $61\\%$ of the $400$ surveyed voters changed their opinion during the survey."},{"key":"D","text":"If the survey were repeated, exactly $57\\%$ of a new sample would support the park renovation."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of $4$ percentage points means we can be reasonably confident the true population proportion falls within $57\\% \\pm 4\\%$, or between $53\\%$ and $61\\%$, of all registered voters. The option stating exactly $57\\%$ ignores sampling variability. The option about surveyed voters changing opinions misinterprets what the margin of error describes. The option predicting an identical result in a new sample confuses the population parameter with the sample statistic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EH9DF3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'If $-4(2n + 3) \\geq 5n - 51$, what is the greatest integer value of $n$ that satisfies the inequality?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distribute the $-4$: $-8n - 12 \\geq 5n - 51$. Add $8n$ to both sides: $-12 \\geq 13n - 51$. Add 51 to both sides: $39 \\geq 13n$. Divide by 13: $3 \\geq n$, so $n \\leq 3$. The greatest integer value is $3$. Verification: at $n = 3$, $-4(9) = -36$ and $5(3) - 51 = -36$, so $-36 \\geq -36$ holds. At $n = 4$, $-4(11) = -44$ and $5(4) - 51 = -31$, so $-44 \\geq -31$ is false. The value $2$ results from an arithmetic slip in dividing $39$ by $13$. The value $4$ comes from a distribution error yielding a weaker inequality. The value $-3$ comes from a sign error when distributing $-4$ across $2n + 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ER7406', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands $137$ meters from the base of a cliff. The angle of elevation from the surveyor''s instrument to the top of the cliff is $23°$, and the instrument is $1.4$ meters above the ground. What is the total height of the cliff, in meters, to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '59.6', ARRAY['298/5', '59.6'], E'Let $h$ be the height of the cliff above the instrument level. Using the tangent ratio, $\\tan(23°) = \\frac{h}{137}$, so $h = 137 \\times \\tan(23°) \\approx 137 \\times 0.4245 \\approx 58.2$ meters. The total height of the cliff is the height above the instrument plus the instrument height: $58.2 + 1.4 = 59.6$ meters.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EWKBV8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the positive solution to the equation $x^2 + 11x - 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-14$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring: $x^2 + 11x - 42 = (x + 14)(x - 3) = 0$, giving $x = -14$ or $x = 3$. The positive solution is $3$. The value $6$ results from an incorrect factoring attempt such as $(x + 7)(x - 6)$, which does not yield the correct middle term. The value $-14$ is the negative solution, not the positive one the question asks for. The value $14$ comes from taking the absolute value of the negative root instead of identifying the actual positive root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F0MS3K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = c \\cdot d^x$, where $c$ and $d$ are positive constants. If $p(1) = 10$ and $p(3) = 640$, what is the value of $p(2)$?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$80$"},{"key":"C","text":"$160$"},{"key":"D","text":"$320$"}]$lyceon_json$::jsonb, 'B', NULL, E'From $p(1) = cd = 10$ and $p(3) = cd^3 = 640$, dividing gives $d^2 = \\frac{640}{10} = 64$, so $d = 8$. Then $c = \\frac{10}{8} = \\frac{5}{4}$. Therefore $p(2) = \\frac{5}{4} \\cdot 8^2 = \\frac{5}{4} \\cdot 64 = 80$. The value $40$ comes from computing $\\frac{10+640}{2}/\\text{something}$ or halving incorrectly. The value $160$ comes from an arithmetic error multiplying $\\frac{5}{4} \\cdot 64$ as $\\frac{5}{4} \\cdot 128$. The value $320$ comes from computing $p(3)/2 = 640/2$ or confusing exponent rules.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FML0V0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A linear function $g$ satisfies $g(3) = 19$ and $g(11) = -13$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '31/4', ARRAY['31/4', '7.75'], E'The slope is $m = \\frac{-13 - 19}{11 - 3} = \\frac{-32}{8} = -4$. Using the point $(3, 19)$: $g(x) = -4(x - 3) + 19 = -4x + 12 + 19 = -4x + 31$. Setting $g(x) = 0$: $-4x + 31 = 0$, so $4x = 31$, giving $x = \\frac{31}{4} = 7.75$. Verification: $g(7.75) = -4(7.75) + 31 = -31 + 31 = 0$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FR0NQ7', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(1, 5)$ and $(4, 17)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 1)$"},{"key":"B","text":"$(0, -1)$"},{"key":"C","text":"$(0, 4)$"},{"key":"D","text":"$(0, 5)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{17 - 5}{4 - 1} = \\frac{12}{3} = 4$. Using point-slope with $(1, 5)$: $y - 5 = 4(x - 1)$, so $y = 4x + 1$. The $y$-intercept is $(0, 1)$. The value $(0, -1)$ is a sign error when computing $5 - 4 = 1$. The value $(0, 4)$ confuses the slope with the intercept. The value $(0, 5)$ uses the $y$-coordinate of the first point without adjustment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FVKACS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher wanted to determine whether a new fertilizer increases tomato yield. She randomly assigned $60$ tomato plants to two groups: $30$ received the new fertilizer and $30$ received no fertilizer. After $8$ weeks, the group that received the new fertilizer had a significantly higher average yield. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer caused the increase in tomato yield for the plants in the study."},{"key":"B","text":"The new fertilizer will increase yield for all tomato varieties grown anywhere."},{"key":"C","text":"The increase in yield was likely due to differences in sunlight between the two groups."},{"key":"D","text":"No conclusion about the fertilizer can be drawn because the sample size is too small."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researcher randomly assigned the plants to treatment and control groups, confounding variables are controlled for, and a causal conclusion can be drawn for the plants in the study. The option generalizing to all tomato varieties everywhere overgeneralizes beyond the study population. The option citing sunlight differences ignores that random assignment controls for such confounders. The option claiming insufficient sample size is incorrect because the study used random assignment and found a statistically significant result, which supports a causal conclusion for the study population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FWPI9W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $5x + 3y = 41$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -2)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-31/5', ARRAY['-31/5', '-6.2'], E'Rewrite line $p$ in slope-intercept form: $3y = -5x + 41$, so $y = -\\frac{5}{3}x + \\frac{41}{3}$. The slope of line $p$ is $-\\frac{5}{3}$. A perpendicular line has slope equal to the negative reciprocal, which is $\\frac{3}{5}$. Using point-slope form with $(7, -2)$: $y + 2 = \\frac{3}{5}(x - 7)$. Distribute: $y + 2 = \\frac{3}{5}x - \\frac{21}{5}$. Subtract $2$: $y = \\frac{3}{5}x - \\frac{21}{5} - \\frac{10}{5} = \\frac{3}{5}x - \\frac{31}{5}$. The $y$-intercept is $-\\frac{31}{5}$, which equals $-6.2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GI7SHR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'When the expression $\\dfrac{6x^4 y^3}{18x^2 y^7}$ is simplified and written in the form $\\dfrac{x^a}{b y^c}$, where $a$, $b$, and $c$ are positive integers, what is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Simplify the coefficients: $\\dfrac{6}{18} = \\dfrac{1}{3}$. For the $x$ terms: $x^{4-2} = x^2$. For the $y$ terms: $y^{3-7} = y^{-4} = \\dfrac{1}{y^4}$. So the expression simplifies to $\\dfrac{x^2}{3y^4}$, giving $a = 2$, $b = 3$, $c = 4$. Therefore $a + b + c = 2 + 3 + 4 = 9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTHUR7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\dfrac{9x^2 - 49}{3x + 7}$ for $x \\neq -\\dfrac{7}{3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 7$"},{"key":"B","text":"$3x - 7$"},{"key":"C","text":"$9x - 7$"},{"key":"D","text":"$3x^2 - 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognize $9x^2 - 49$ as a difference of squares: $(3x)^2 - 7^2 = (3x + 7)(3x - 7)$. Dividing by $(3x + 7)$ cancels that factor, leaving $3x - 7$. The option $3x + 7$ uses the wrong factor after cancellation, a sign error. The option $9x - 7$ fails to take the square root of $9x^2$ properly. The option $3x^2 - 7$ incorrectly divides only the constant while leaving the $x^2$ term partially simplified.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2II9KRK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\dfrac{4x^3 + 10x^2 - 30x}{2x}$ is rewritten in the form $ax^2 + bx + c$, where $a$, $b$, and $c$ are constants and $x \\neq 0$, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-10$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$-8$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Divide each term of the numerator by $2x$: $\\dfrac{4x^3}{2x} = 2x^2$, $\\dfrac{10x^2}{2x} = 5x$, and $\\dfrac{-30x}{2x} = -15$. So $a = 2$, $b = 5$, $c = -15$, and $a + b + c = 2 + 5 + (-15) = -8$. The option $-10$ arises from an arithmetic slip such as computing $\\dfrac{10x^2}{2x} = 3x$ instead of $5x$. The option $-6$ results from partial reasoning, such as miscomputing $c$ as $-13$ from an incomplete division. The option $6$ flips the sign of $c$, treating $-15$ as $+15$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J8XC7S', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is one solution to the equation $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor $x^2 - 11x + 28$ by finding two numbers that multiply to $28$ and add to $-11$: those are $-4$ and $-7$, so $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$. The solutions are $x = 4$ and $x = 7$, so $4$ is correct. The value $3$ does not satisfy the equation since $9 - 33 + 28 = 4 \\neq 0$. The value $-4$ is a sign error, confusing the factor $-4$ with the root. The value $11$ mistakes the sum of the roots for a root itself, a conceptual error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JR5UU4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ if $\\sqrt{x + 13} = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$62$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'A', NULL, E'Squaring both sides: $x + 13 = 49$, so $x = 36$. The value $62$ results from computing $49 + 13 = 62$, adding instead of subtracting. The value $-6$ results from a sign error such as $7 - 13 = -6$, subtracting without squaring first. The value $20$ results from an arithmetic slip such as $49 - 13 = 20$ instead of $36$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K4EX5W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'The equation $9x + 4y = 36$ represents a line. What is the $x$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 0)$"},{"key":"B","text":"$(0, 9)$"},{"key":"C","text":"$(9, 0)$"},{"key":"D","text":"$(0, 4)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting: $9x + 4(0) = 36$, so $9x = 36$ and $x = 4$. The $x$-intercept is $(4, 0)$. The point $(0, 9)$ confuses the $x$-intercept with the $y$-intercept and computes $36/4 = 9$ on the wrong axis. The point $(9, 0)$ uses the coefficient of $x$ as the $x$-coordinate rather than solving the equation. The point $(0, 4)$ correctly computes $36/9 = 4$ but places it on the $y$-axis instead of the $x$-axis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K8QU3A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $DEF$, angle $D$ measures $53°$ and angle $E$ measures $71°$. What is the measure, in degrees, of angle $F$?', NULL, $lyceon_json$[{"key":"A","text":"$46°$"},{"key":"B","text":"$56°$"},{"key":"C","text":"$124°$"},{"key":"D","text":"$66°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of angles in a triangle is $180°$. So angle $F = 180° - 53° - 71° = 56°$. The value $46°$ comes from an arithmetic error ($180 - 53 - 71 = 46$ by miscalculating). The value $124°$ computes $53 + 71 = 124$ but forgets to subtract from $180$. The value $66°$ subtracts only one angle: $180 - 53 - 71$ miscalculated as $66$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L7EPS7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $2x^2 + 13x - 24 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/2', ARRAY['3/2', '1.5'], E'To factor $2x^2 + 13x - 24$, find two numbers that multiply to $2 \\cdot (-24) = -48$ and add to $13$: those are $16$ and $-3$. Rewrite the middle term: $2x^2 + 16x - 3x - 24 = 2x(x + 8) - 3(x + 8) = (2x - 3)(x + 8) = 0$. Setting each factor to zero gives $x = \\dfrac{3}{2}$ or $x = -8$. Since $x > 0$, the answer is $\\dfrac{3}{2}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LN7DHK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store marks up a wholesale item by $35\\%$ of the wholesale price, then offers a $20\\%$ discount on the marked-up price during a sale. If the wholesale price of the item is $\\$74$, what is the sale price?', NULL, $lyceon_json$[{"key":"A","text":"$\\$79.92$"},{"key":"B","text":"$\\$85.10$"},{"key":"C","text":"$\\$88.80$"},{"key":"D","text":"$\\$79.20$"}]$lyceon_json$::jsonb, 'A', NULL, E'The marked-up price is $74 \\times 1.35 = 99.90$. A $20\\%$ discount on $\\$99.90$ means the sale price is $99.90 \\times 0.80 = 79.92$. The value $\\$85.10$ results from computing the markup correctly as $\\$99.90$ but then subtracting $20\\%$ of the original $\\$74$ (which is $\\$14.80$) instead of $20\\%$ of $\\$99.90$. The value $\\$88.80$ comes from computing $74 \\times 1.20 = 88.80$, treating the combined effect as a net $20\\%$ increase. The value $\\$79.20$ results from rounding $\\$99.90$ down to $\\$99$ before applying the $20\\%$ discount, yielding $99 \\times 0.80 = 79.20$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LNI77B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'grid_in', E'In a class of $40$ students, $23$ play soccer and $18$ play basketball. If $9$ students play both soccer and basketball, what is the probability that a randomly selected student plays neither sport? Express your answer as a decimal.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '.2', ARRAY['1/5', '0.2', '.2'], E'Using the inclusion-exclusion principle, the number of students who play at least one sport is $23 + 18 - 9 = 32$. The number of students who play neither sport is $40 - 32 = 8$. The probability is $\\frac{8}{40} = 0.2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NVGXPP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains $9$ values: $11, 14, 14, 17, 19, 22, 22, 22, 31$. What is the interquartile range of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The $9$ values in order are $11, 14, 14, 17, 19, 22, 22, 22, 31$. The median is the $5$th value, which is $19$. The lower half is $11, 14, 14, 17$, so $Q_1 = \\frac{14 + 14}{2} = 14$. The upper half is $22, 22, 22, 31$, so $Q_3 = \\frac{22 + 22}{2} = 22$. The interquartile range is $Q_3 - Q_1 = 22 - 14 = 8$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWC6BX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $4(3x + 5) - 2(x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$10x + 38$"},{"key":"B","text":"$10x + 2$"},{"key":"C","text":"$14x + 38$"},{"key":"D","text":"$10x - 38$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute: $4(3x + 5) = 12x + 20$ and $-2(x - 9) = -2x + 18$. Combine: $12x + 20 - 2x + 18 = 10x + 38$. The value $10x + 2$ comes from subtracting $18$ instead of adding it. The value $14x + 38$ comes from adding $12x + 2x$ instead of subtracting. The value $10x - 38$ comes from distributing the negative incorrectly to both terms in $(3x + 5)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWRID9', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = -3x + 47$. What is the value of $f(13)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Substitute $x = 13$ into $f(x) = -3x + 47$: $f(13) = -3(13) + 47 = -39 + 47 = 8$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PJFFVE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $4x^2 \\cdot 3x^5$?', NULL, $lyceon_json$[{"key":"A","text":"$12x^{10}$"},{"key":"B","text":"$7x^7$"},{"key":"C","text":"$12x^7$"},{"key":"D","text":"$7x^{10}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying the coefficients gives $4 \\cdot 3 = 12$, and adding the exponents gives $x^{2+5} = x^7$. The result is $12x^7$. The expression $12x^{10}$ results from multiplying the exponents ($2 \\cdot 5 = 10$) instead of adding them. The expression $7x^7$ results from adding the coefficients ($4 + 3 = 7$) instead of multiplying. The expression $7x^{10}$ commits both errors simultaneously.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PK2TNB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles measures $34°$. The side adjacent to this angle has length $19$. What is the length of the hypotenuse, to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$22.9$"},{"key":"B","text":"$10.6$"},{"key":"C","text":"$33.9$"},{"key":"D","text":"$15.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using $\\cos(34°) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{19}{h}$, we get $h = \\frac{19}{\\cos(34°)} = \\frac{19}{0.8290} \\approx 22.9$. The value $10.6$ results from multiplying $19 \\times \\sin(34°) \\approx 19 \\times 0.5592 \\approx 10.6$, which finds the opposite side rather than the hypotenuse. The value $33.9$ comes from dividing by $\\sin(34°)$ instead of $\\cos(34°)$, confusing the two ratios. The value $15.7$ results from computing $19 \\times \\cos(34°) \\approx 15.7$, which multiplies by cosine instead of dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2POSOP0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $13$ meters and a width of $7$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '91', ARRAY['91'], E'The area of a rectangle is $A = l \\times w = 13 \\times 7 = 91$ square meters.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QEI2ON', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges $\\$6$ per package plus a flat fee of $\\$23$ for pickup. A customer has a budget of at most $\\$125$ for shipping. What is the maximum number of packages the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$17$"},{"key":"C","text":"$20$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'The inequality is $6n + 23 \\leq 125$. Subtracting $23$: $6n \\leq 102$. Dividing by $6$: $n \\leq 17$. Since $n$ must be a whole number, the maximum is $17$. A student who uses strict inequality or rounds down unnecessarily answers $16$. A student who omits the flat fee solves $6n \\leq 125$, getting $n \\leq 20.83$, and answers $20$. A student who divides $125$ by $6$ and rounds up to the nearest whole number gets $21$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QLJJIH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $5x - 2y = 11$ and $15x - 6y = k$ have infinitely many solutions?', NULL, $lyceon_json$[{"key":"A","text":"$33$"},{"key":"B","text":"$22$"},{"key":"C","text":"$-33$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the system to have infinitely many solutions, the second equation must be a constant multiple of the first. The left side of the second equation is $15x - 6y = 3(5x - 2y)$, so the multiplier is 3. The right side must also be multiplied by 3: $k = 3 \\times 11 = 33$. The value $22$ comes from multiplying 11 by 2 instead of 3, perhaps from comparing only one pair of coefficients. The value $-33$ is a sign error, negating the correct result. The value $11$ assumes the constants must be identical for infinitely many solutions, ignoring that the coefficients were scaled by 3.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QSS5AQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'An exponential function is defined by $f(x) = 250 \\cdot \\left(\\frac{4}{5}\\right)^x$. What is the value of $f(2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '160', ARRAY['160'], E'Substituting $x = 2$: $f(2) = 250 \\cdot \\left(\\frac{4}{5}\\right)^2 = 250 \\cdot \\frac{16}{25} = \\frac{250 \\cdot 16}{25} = 10 \\cdot 16 = 160$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ROKP1C', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $\\frac{3(2x - 1)}{5} - \\frac{x + 4}{3} = \\frac{7x - 23}{15}$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$1$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$\\frac{1}{6}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply every term by 15 (the LCD of 5, 3, and 15): $15 \\cdot \\frac{3(2x-1)}{5} - 15 \\cdot \\frac{x+4}{3} = 15 \\cdot \\frac{7x-23}{15}$. This yields $9(2x - 1) - 5(x + 4) = 7x - 23$. Expanding: $18x - 9 - 5x - 20 = 7x - 23$, so $13x - 29 = 7x - 23$. Subtracting $7x$ from both sides gives $6x - 29 = -23$, and adding 29 gives $6x = 6$, so $x = 1$. The value $6$ comes from stopping at $6x = 6$ and reporting the coefficient rather than dividing. The value $-1$ is a sign error when solving $6x = 6$. The value $\\frac{1}{6}$ results from inverting the final division, computing $\\frac{1}{6}$ instead of $\\frac{6}{6}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RUY0QX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{9x^4 - 25y^6}{3x^2 + 5y^3}$, where $3x^2 + 5y^3 \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 5y^3$"},{"key":"B","text":"$3x^2 - 5y^3$"},{"key":"C","text":"$9x^4 - 5y^3$"},{"key":"D","text":"$3x^2 - 25y^6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognizing $9x^4 - 25y^6 = (3x^2)^2 - (5y^3)^2$, this is a difference of squares: $(3x^2 + 5y^3)(3x^2 - 5y^3)$. Dividing by $(3x^2 + 5y^3)$ leaves $3x^2 - 5y^3$. The expression $3x^2 + 5y^3$ results from using the wrong factor after cancellation (sign error in the factoring). The expression $9x^4 - 5y^3$ results from only partially simplifying, dividing the second term but not recognizing the squared structure of the first. The expression $3x^2 - 25y^6$ comes from taking the square root of only one term in the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TLLCG6', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $9x - 4y = 36$ represents a line in the $xy$-plane. What is the $x$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 0)$"},{"key":"B","text":"$(9, 0)$"},{"key":"C","text":"$(0, -9)$"},{"key":"D","text":"$(-4, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the $x$-intercept, set $y = 0$: $9x - 4(0) = 36$, so $9x = 36$, giving $x = 4$. The $x$-intercept is $(4, 0)$. A student who mistakes the coefficient of $x$ for the intercept answers $(9, 0)$. A student who sets $x = 0$ instead finds $-4y = 36$, giving $y = -9$, and writes $(0, -9)$, which is the $y$-intercept rather than the $x$-intercept. A student who introduces a sign error when solving $9x = 36$ arrives at $x = -4$, yielding $(-4, 0)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TYQ7B5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 10x + 6y - 47 = 0$. What is the distance from the center of this circle to the line $4x + 3y = 26$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$9$"},{"key":"C","text":"$\\frac{11}{5}$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, complete the square: $x^2 - 10x + 25 + y^2 + 6y + 9 = 47 + 25 + 9 = 81$, giving $(x - 5)^2 + (y + 3)^2 = 81$. The center is $(5, -3)$ and the radius is $9$. The distance from $(5, -3)$ to the line $4x + 3y - 26 = 0$ is $\\frac{|4(5) + 3(-3) - 26|}{\\sqrt{4^2 + 3^2}} = \\frac{|20 - 9 - 26|}{\\sqrt{25}} = \\frac{|-15|}{5} = 3$. The value $9$ is simply the radius, which confuses the distance to a line with the radius. The value $\\frac{11}{5}$ results from computing $\\frac{|20 - 9|}{5}$ and forgetting to subtract $26$. The value $5$ comes from using $\\sqrt{25} = 5$ as the answer rather than the denominator in the distance formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U48C8P', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-3, 11)$ and $(4, -17)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{-17 - 11}{4 - (-3)} = \\frac{-28}{7} = -4$. Using the point $(-3, 11)$ in $y = mx + b$: $11 = -4(-3) + b$, so $11 = 12 + b$, giving $b = -1$. The $y$-intercept is $-1$. The value $1$ results from a sign error when computing $11 - 12$. The value $-7$ comes from an arithmetic slip such as computing $\\frac{-28}{4}$ instead of $\\frac{-28}{7}$ and confusing the slope with the intercept. The value $7$ comes from reversing the order of points in the slope formula and making a subsequent error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WYXOE1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $JKL$, point $M$ lies on $\\overline{JK}$ and point $N$ lies on $\\overline{JL}$ such that $\\overline{MN}$ is parallel to $\\overline{KL}$. If $JM = 8$, $MK = 6$, and the area of triangle $JMN$ is $48$, what is the area of trapezoid $MNLK$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '99', ARRAY['99'], E'Since $\\overline{MN}$ is parallel to $\\overline{KL}$, triangles $JMN$ and $JKL$ are similar. The ratio of corresponding sides is $\\frac{JM}{JK} = \\frac{8}{8 + 6} = \\frac{8}{14} = \\frac{4}{7}$. The ratio of their areas is the square of the side ratio: $\\left(\\frac{4}{7}\\right)^2 = \\frac{16}{49}$. Since the area of triangle $JMN$ is $48$, the area of triangle $JKL$ is $48 \\times \\frac{49}{16} = 147$. The area of trapezoid $MNLK$ is the area of triangle $JKL$ minus the area of triangle $JMN$: $147 - 48 = 99$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XDPFJ4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 2(3)^x$. Which of the following statements correctly describes the behavior of $g$?', NULL, $lyceon_json$[{"key":"A","text":"As $x$ increases, $g(x)$ increases at a constant rate."},{"key":"B","text":"As $x$ increases, $g(x)$ increases at an increasing rate."},{"key":"C","text":"As $x$ increases, $g(x)$ decreases at a decreasing rate."},{"key":"D","text":"As $x$ increases, $g(x)$ approaches $0$."}]$lyceon_json$::jsonb, 'B', NULL, E'The function $g(x) = 2(3)^x$ is an exponential growth function with base $3 > 1$. As $x$ increases, the output grows and the rate of growth itself increases (exponential growth). The claim that $g(x)$ increases at a constant rate describes a linear function, not an exponential one. The claim that $g(x)$ decreases at a decreasing rate describes exponential decay with a base between $0$ and $1$. The claim that $g(x)$ approaches $0$ describes the end behavior of an exponential decay function as $x \\to \\infty$, not growth.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XJ1FFH', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{5x + 7}{3} = 2x + 9$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-20', ARRAY['-20'], E'Multiply both sides by 3: $5x + 7 = 6x + 27$. Subtract $5x$ from both sides: $7 = x + 27$. Subtract 27 from both sides: $x = -20$. Verification: $\\frac{5(-20) + 7}{3} = \\frac{-93}{3} = -31$ and $2(-20) + 9 = -40 + 9 = -31$. Both sides equal $-31$, confirming the solution.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y0EDFK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 4x + 7$ and $y = 2x - k$ has exactly one real solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the two expressions equal: $x^2 - 4x + 7 = 2x - k$, which rearranges to $x^2 - 6x + (7 + k) = 0$. For exactly one real solution, the discriminant must equal zero: $(-6)^2 - 4(1)(7 + k) = 0$, so $36 - 28 - 4k = 0$, giving $8 = 4k$ and $k = 2$. The value $-2$ is a sign error from solving $-4k = 8$ instead of $-4k = -8$. The value $-3$ results from an equation setup error such as writing the constant term as $(7 - k)$ instead of $(7 + k)$. The value $5$ arises from partial reasoning, such as using the wrong coefficient in the linear term when forming the quadratic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZR5DDJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 7)}{4} + 5 = \\frac{x + 11}{2}$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23/4', ARRAY['23/4', '5.75'], E'Multiply both sides by $4$ to clear fractions: $3(2x - 7) + 20 = 2(x + 11)$. Expand: $6x - 21 + 20 = 2x + 22$. Simplify the left side: $6x - 1 = 2x + 22$. Subtract $2x$ from both sides: $4x - 1 = 22$. Add $1$ to both sides: $4x = 23$. Divide by $4$: $x = \\frac{23}{4}$. Verification: left side equals $\\frac{3(2 \\cdot 5.75 - 7)}{4} + 5 = \\frac{3(4.5)}{4} + 5 = \\frac{13.5}{4} + 5 = 3.375 + 5 = 8.375$. Right side equals $\\frac{5.75 + 11}{2} = \\frac{16.75}{2} = 8.375$. Both sides match, confirming $x = \\frac{23}{4}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZYFS65', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cone has a height of $11$ centimeters and a base radius of $6$ centimeters. What is the volume, in cubic centimeters, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$132\\pi$"},{"key":"B","text":"$396\\pi$"},{"key":"C","text":"$66\\pi$"},{"key":"D","text":"$264\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(6)^2(11) = \\frac{1}{3}\\pi(396) = 132\\pi$. The value $396\\pi$ results from computing $\\pi r^2 h$ without the $\\frac{1}{3}$ factor, which is the cylinder volume formula. The value $66\\pi$ comes from using $\\frac{1}{3}\\pi r h = \\frac{1}{3}\\pi(6)(11)$ without squaring the radius. The value $264\\pi$ arises from using $\\frac{2}{3}\\pi r^2 h$ instead of $\\frac{1}{3}$, confusing the cone formula with the hemisphere formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZYH1DX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = -5x + 22$. What is the value of $h(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$37$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 3$: $h(3) = -5(3) + 22 = -15 + 22 = 7$. The value $37$ comes from adding $15 + 22$ instead of $-15 + 22$. The value $-7$ reverses the subtraction to get $15 - 22$. The value $15$ is the intermediate product $5 \\cdot 3$ before applying the negative sign and adding $22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW201LSNT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A recent archaeological survey of the Faiyum Oasis in Egypt revealed that neither the limestone quarry tools found at the northern excavation site nor the copper chisel recovered from a sealed burial chamber ______ consistent with construction methods documented in records from the Fourth Dynasty, suggesting that the artifacts may predate the known timeline of pyramid building.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were being"},{"key":"D","text":"have been consistently"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the nearer subject. Here the nearer subject is "the copper chisel recovered from a sealed burial chamber," which is singular, so the verb must be singular. Additionally, the sentence describes the findings of a completed survey ("revealed that"), calling for a past-tense or simple present reporting form; the simple past singular "is" used in the reported clause (introduced by "revealed that") functions as a present-tense finding within the reported context, correctly agreeing with the singular nearer subject. The option "are" is plural and fails to agree with the singular nearer subject "chisel." The option "were being" introduces a past progressive tense that implies the artifacts were in the process of becoming consistent, which is semantically nonsensical—consistency with documented methods is a static property, not an ongoing action. The option "have been consistently" shifts to present perfect tense and introduces the adverb "consistently," which alters the meaning to suggest repeated demonstrations of consistency rather than a simple finding of the survey, and its plural form also fails to agree with the singular nearer subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21JI6AF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis described in the text?', E'The following passage is from a 2022 report on sleep and memory consolidation. Neuroscientists at the University of Zurich hypothesized that targeted memory reactivation during slow-wave sleep could strengthen retention of newly learned vocabulary in a second language. In their proposed mechanism, auditory cues played during deep sleep would reactivate the neural traces formed during waking study, thereby reinforcing the associations between foreign words and their meanings without requiring additional conscious rehearsal.', $lyceon_json$[{"key":"A","text":"Participants who heard vocabulary cues during slow-wave sleep recalled significantly more foreign words the next morning than those who slept without auditory cues."},{"key":"B","text":"Participants who studied vocabulary lists for twice as long before sleeping performed better on recall tests regardless of whether auditory cues were played during the night."},{"key":"C","text":"Auditory cues played during REM sleep, rather than slow-wave sleep, produced the strongest improvements in vocabulary recall among all tested conditions."},{"key":"D","text":"Participants who received auditory cues while awake during a rest period showed recall improvements comparable to those observed in sleeping participants who received the same cues."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis states that auditory cues during slow-wave sleep reinforce vocabulary retention. A finding that participants who heard cues during slow-wave sleep recalled significantly more words directly supports this claim by showing the predicted effect. The option about longer study time improving recall regardless of cues would support a study-duration explanation rather than the sleep-cue hypothesis. The option about REM sleep producing stronger results would actually undermine the hypothesis, which specifies slow-wave sleep as the critical phase. The option about awake rest periods producing comparable results would suggest sleep is not necessary for the cue effect, weakening rather than supporting the hypothesis that slow-wave sleep is the operative mechanism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22YPJ1W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1897, the mathematician Hermann Minkowski proposed a novel geometric framework for understanding number theory. His approach treated algebraic problems as questions about lattice points in multidimensional ______ this framework later proved essential to Einstein''s formulation of special relativity, a connection Minkowski himself did not foresee.', $lyceon_json$[{"key":"A","text":"space, but"},{"key":"B","text":"space but"},{"key":"C","text":"space;"},{"key":"D","text":"space, and so"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank joins two independent clauses. A semicolon correctly links two closely related independent clauses without a coordinating conjunction. The option "space, but" is incorrect because the second clause does not present a contrast to the first—it extends the idea by noting a later application, making "but" semantically wrong. The option "space but" omits the required comma before a coordinating conjunction joining two independent clauses, violating standard comma-before-conjunction usage. The option "space, and so" is incorrect because "and so" implies the second event was a direct logical consequence of the first, but the passage states that Minkowski himself did not foresee the connection, undermining a causal reading.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23SDMU0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "eclipsed" most nearly means', E'The ceramic traditions of the Jomon period, which flourished in the Japanese archipelago for roughly fourteen thousand years, were eventually <u>eclipsed</u> by the introduction of Yayoi-era techniques around 300 BCE. The newer methods, emphasizing uniformity and functional simplicity, gradually displaced the elaborate cord-marked designs that had defined Jomon artisanship.', $lyceon_json$[{"key":"A","text":"overshadowed"},{"key":"B","text":"darkened"},{"key":"C","text":"celebrated"},{"key":"D","text":"concealed from public view"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how newer Yayoi techniques gradually displaced the older Jomon traditions, meaning the Jomon methods were surpassed in prominence. "Overshadowed" accurately conveys this sense of being exceeded in importance. "Darkened" applies the astronomical or literal meaning of eclipse, which is irrelevant to the context of cultural traditions. "Celebrated" directly contradicts the passage''s description of displacement. "Concealed from public view" suggests deliberate hiding, which goes beyond what the passage describes — the traditions were simply surpassed, not intentionally hidden.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
