INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29LBIWX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers studying bioluminescence in deep-sea environments have documented over seventy species of cnidarians that produce light through chemical reactions involving the protein ______ some of these organisms use bioluminescence to attract prey, others deploy it as a defense mechanism, releasing bright flashes to startle approaching predators.', $lyceon_json$[{"key":"A","text":"aequorin. While"},{"key":"B","text":"aequorin while"},{"key":"C","text":"aequorin, while"},{"key":"D","text":"aequorin; while"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank must end the first independent clause (about researchers documenting cnidarians) and begin a new sentence that opens with the subordinating conjunction "while" to introduce a contrast between two uses of bioluminescence. The option using a period followed by a capitalized "While" correctly ends the first sentence and begins a new one with a dependent clause that leads into the independent clause about defense mechanisms. The option "aequorin while" (no punctuation) creates a run-on by fusing two complete thoughts without any boundary marker. The option "aequorin, while" creates a comma splice: the material after "while" contains two independent clauses joined by a comma ("some...prey, others deploy it..."), so attaching the entire structure to the first clause with only a comma produces an ungrammatical run-on. The option using a semicolon before "while" is incorrect because a semicolon should join two independent clauses, but "while some of these organisms use bioluminescence to attract prey" is a dependent clause, not an independent one—a semicolon before a subordinating conjunction violates standard boundary conventions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AQCEJ0', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Anika Patel has documented the migration patterns of leatherback sea turtles across the Indian Ocean. Her research reveals that these turtles travel over 7,300 miles annually between nesting grounds in Sri Lanka and feeding areas near the coast of South Africa. ______ Patel''s tracking data has prompted several coastal nations to establish new protected marine corridors.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"As a result,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Patel''s finding about the vast migration distances of leatherback sea turtles, and the sentence that follows describes a consequence of that finding: nations establishing protected corridors. The transition "As a result," correctly signals this cause-and-effect relationship. "In other words," incorrectly signals a restatement, but the final sentence introduces new information rather than rephrasing. "On the contrary," incorrectly signals a contradiction, yet establishing marine corridors is consistent with, not opposed to, the research. "For instance," incorrectly signals an example, but the creation of marine corridors is a consequence of the research, not an illustration of it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BEVFQE', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Caspian seal, one of the smallest pinniped species in the world, relies on winter ice formations in the northern Caspian Sea for breeding ______ without stable ice platforms during the coldest months, pups face dramatically higher mortality rates.', $lyceon_json$[{"key":"A","text":"and breeding."},{"key":"B","text":"and breeding,"},{"key":"C","text":"for breeding,"},{"key":"D","text":"for breeding."}]$lyceon_json$::jsonb, 'D', NULL, E'The blank separates two independent clauses: the first describes the seal’s reliance on ice formations, and the second (beginning with “without stable ice platforms”) presents a consequence. A period correctly ends the first sentence and allows the second to stand as its own sentence. The option ending with “and breeding.” incorrectly inserts a conjunction that disrupts the meaning by suggesting an additional activity rather than ending the clause. The option ending with “and breeding,” creates a comma splice by joining two independent clauses with only a comma after a conjunction fragment. The option ending with “for breeding,” produces a comma splice—two independent clauses joined by only a comma, which violates Standard English conventions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EMRCK5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Computational linguist Farah El-Masri developed an algorithm that identifies dialectal variations in 14th-century Arabic manuscripts by analyzing letter-spacing patterns invisible to the human eye. Her tool classified a set of 53 previously unattributed manuscripts with 91 percent accuracy when tested against expert attributions. The algorithm struggles, however, with documents that have been heavily restored, since modern conservators often regularize spacing to improve legibility. ______ El-Masri has begun collaborating with conservators to develop restoration protocols that preserve the original spacing data her algorithm depends on.', $lyceon_json$[{"key":"A","text":"To address this limitation,"},{"key":"B","text":"In addition to this finding,"},{"key":"C","text":"Regardless of these concerns,"},{"key":"D","text":"To illustrate this accomplishment,"}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentence identifies a specific limitation: the algorithm fails with heavily restored documents because conservators regularize spacing. The final sentence describes El-Masri''s response to that limitation, collaborating with conservators to preserve original spacing. "To address this limitation," correctly signals a purposeful response to the problem just described. "In addition to this finding," incorrectly treats the limitation as a finding to be supplemented, but the final sentence is a corrective action, not a separate discovery. "Regardless of these concerns," incorrectly implies that El-Masri is proceeding despite the limitation, when the final sentence describes directly engaging with it. "To illustrate this accomplishment," misreads the preceding context as describing an achievement, when it in fact describes a shortcoming of the algorithm.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FNU9GS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The muralist Judith Baca, renowned for her collaborative public art projects in Los Angeles, ______ a half-mile-long mural depicting the history of California from prehistoric times through the 1980s.', $lyceon_json$[{"key":"A","text":"have created"},{"key":"B","text":"creating"},{"key":"C","text":"created"},{"key":"D","text":"create, having been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is the singular noun "Judith Baca," so the verb must agree in number and provide a finite, past-tense form to match the historical time frame (the 1980s). The simple past tense "created" correctly agrees with the singular subject and fits the past context. The option "have created" uses a plural verb form that does not agree with the singular subject "Judith Baca." The option "creating" is a present participle that cannot serve as the main verb of the sentence, producing a fragment. The option "create, having been" uses a base form that does not agree with a singular third-person subject and appends an incomplete participial phrase, resulting in an ungrammatical construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FPH36L', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the second study, if true, would most directly weaken the conclusion drawn from the first study described in the text?', E'The following passage is from a 2023 review article on environmental psychology. A 2019 study conducted in Oslo measured cortisol levels in 83 office workers before and after a 40-minute midday walk. Participants who walked through a forested park showed a 23% reduction in salivary cortisol, while those who walked through a commercial district showed only a 7% reduction. The researchers concluded that exposure to natural environments, rather than physical activity alone, was the primary driver of acute stress reduction. A separate 2021 study in Singapore, however, examined whether sensory complexity — defined as the diversity of sounds, colors, and textures in a given environment — might be a confounding variable overlooked in nature-versus-urban walking studies.', $lyceon_json$[{"key":"A","text":"Participants who walked through a sensory-rich urban arts district with diverse colors, sounds, and textures showed cortisol reductions comparable to those observed in the Oslo forested-park group."},{"key":"B","text":"Participants who walked through a manicured urban plaza with minimal vegetation but low sensory complexity showed cortisol reductions significantly smaller than those observed in the Oslo commercial-district group."},{"key":"C","text":"Participants who sat quietly in a forested park without walking showed cortisol reductions comparable to those observed in the Oslo forested-park walking group, supporting the role of nature over activity."},{"key":"D","text":"Participants who walked through a dense tropical forest with high sensory complexity showed cortisol reductions significantly larger than those observed in participants who walked through a sparse grassland with low sensory complexity."}]$lyceon_json$::jsonb, 'A', NULL, E'The Oslo study concluded that natural environments, not just physical activity, drive stress reduction. If a sensory-rich urban environment without nature produced comparable cortisol reductions, this would suggest sensory complexity — not nature per se — explains the effect, directly weakening the Oslo conclusion. The finding about a low-complexity urban plaza showing even smaller cortisol reductions than the Oslo commercial group does not challenge the nature hypothesis; it could be interpreted as consistent with it, since a less stimulating urban environment fared worse. The finding about sitting quietly in a forest supports rather than weakens the Oslo conclusion by reinforcing the role of nature over activity. The finding comparing a dense forest to sparse grassland compares two natural environments rather than testing whether a non-natural environment with high sensory complexity could replicate the effect, so it does not isolate sensory complexity as the confounding variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I3M2KH', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'In contemporary philosophy of mind, the "hard problem of consciousness" refers to the difficulty of explaining why subjective experience accompanies neural processes at all. Neuroscientist Giulio Tononi''s Integrated Information Theory (IIT) proposes that consciousness corresponds to a measurable quantity — phi — representing the degree to which a system integrates information beyond the capacity of its parts. <u>Critics such as Hakwan Lau have countered that phi, as currently formulated, cannot distinguish between systems that genuinely experience and those that merely process information in structurally complex ways, rendering the theory unfalsifiable in practice.</u> Tononi has responded by refining the mathematical axioms underlying phi, though whether these refinements adequately address the falsifiability objection remains an active area of dispute.', $lyceon_json$[{"key":"A","text":"It presents an objection that targets a specific limitation of the theory outlined in the preceding sentence."},{"key":"B","text":"It offers an alternative theory of consciousness that directly competes with Integrated Information Theory."},{"key":"C","text":"It concedes that the hard problem of consciousness is fundamentally beyond the reach of empirical science."},{"key":"D","text":"It explains the mathematical procedures Tononi uses to calculate phi in experimental laboratory settings."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents Lau''s criticism that phi cannot distinguish genuine experience from complex information processing, which directly challenges a specific claim of IIT described in the prior sentence. This makes it an objection targeting a particular limitation. The option about an alternative theory mischaracterizes the criticism; Lau''s objection identifies a flaw in IIT but does not propose a replacement framework. The option about conceding that consciousness is beyond science overgeneralizes; the criticism addresses falsifiability of one specific measure, not the entire scientific study of consciousness. The option about explaining mathematical procedures contradicts the content of the underlined sentence, which critiques phi rather than describing how it is calculated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I51ZMQ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Paleoclimatologists have long relied on ice-core records from Greenland and Antarctica to reconstruct temperature fluctuations over the past eight hundred thousand years. These cores trap ancient air bubbles whose isotopic ratios serve as proxies for atmospheric composition at the time of deposition. <u>However, a 2022 study by Renata Alves and colleagues demonstrated that microbial activity within certain ice layers can alter the concentration of methane trapped in bubbles, introducing a systematic bias into the reconstructed record.</u> Alves proposed a correction protocol that adjusts for microbial contamination by cross-referencing methane readings with independent marine-sediment data.', $lyceon_json$[{"key":"A","text":"It introduces a complication that qualifies the reliability of the methodology described earlier in the passage."},{"key":"B","text":"It summarizes the consensus view among paleoclimatologists regarding the interpretation of ice-core data."},{"key":"C","text":"It provides evidence that marine-sediment records are more accurate proxies than ice cores for studying ancient climates."},{"key":"D","text":"It explains why researchers initially chose ice cores over other geological archives for climate reconstruction."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first establishes that ice-core records are a standard tool for climate reconstruction and explains how they work. The underlined sentence, introduced by "However," presents Alves''s finding that microbial activity can distort methane readings, thereby complicating or qualifying the reliability of that standard tool. The option about summarizing consensus misidentifies the underlined sentence''s role; it presents a challenge to prevailing methods, not an endorsement. The option about marine-sediment accuracy overstates the passage, which mentions marine sediments only as a cross-referencing tool, not as a superior alternative. The option about why researchers chose ice cores attributes an explanatory function that the underlined sentence does not perform.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ITW9NL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about urban beekeeping and wants to emphasize the economic benefit it provides to local businesses. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JYXDBX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the work of geochemist Dr. Tomoko Sato and wants to present a finding that challenges a commonly held assumption about volcanic soil. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M01ZMK', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Unlike conventional telescope mirrors, which are manufactured from a single piece of glass and polished to extreme precision, the segmented mirrors used in the Thirty Meter Telescope ______ of 492 individual hexagonal panels, each adjusted by computer-controlled actuators to function as a unified reflective surface.', $lyceon_json$[{"key":"A","text":"is composed"},{"key":"B","text":"composing"},{"key":"C","text":"are composed"},{"key":"D","text":"has been composed"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject is "the segmented mirrors," which is plural, so the verb must be plural as well. "Are composed" correctly provides a plural present-tense passive verb that agrees with "mirrors." The option "is composed" uses a singular verb that does not agree with the plural subject "mirrors." The option "composing" is a participle that cannot serve as the main verb, leaving the sentence without a finite verb and creating a fragment. The option "has been composed" uses a singular auxiliary ("has") that fails to agree with the plural subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M9N7XT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "tenuous" most nearly means', E'In a 2019 paper published in the Journal of Freshwater Ecology, marine biologist Hana Okoro documented the <u>tenuous</u> link between seasonal algal blooms and the migratory patterns of juvenile salmon in the Klamath River basin. While prior researchers had assumed a robust correlation, Okoro''s data revealed that the relationship depended on a narrow set of conditions rarely met outside laboratory settings.', $lyceon_json$[{"key":"A","text":"fragile"},{"key":"B","text":"elongated"},{"key":"C","text":"disputed"},{"key":"D","text":"invisible"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a link that depends on a narrow set of conditions rarely met, indicating the connection is weak and easily disrupted. "Fragile" captures this sense of being delicate and prone to breaking down. "Elongated" misapplies a physical meaning unrelated to the strength of a relationship. "Disputed" goes beyond the passage, which describes the link as weak rather than contested by other researchers. "Invisible" contradicts the passage, since the link was documented, not undetectable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RA6FQY', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between the two properties of aerogels discussed by the author?', E'The following passage is from a 2023 materials science review. Silica aerogels are among the least dense solid materials ever produced, with some variants consisting of more than 99.8% air by volume. This extreme porosity gives aerogels extraordinary thermal insulation properties — a two-centimeter slab can protect a human hand from a blowtorch flame — yet it simultaneously renders them exceptionally fragile. The compressive strength of a standard silica aerogel is roughly 0.3 megapascals, meaning that a modest mechanical load can shatter the material into powder. Recent work at the Karlsruhe Institute of Technology has explored polymer-crosslinked aerogels that sacrifice a portion of insulation performance, accepting thermal conductivity values approximately 40% higher than pure silica aerogels, in exchange for compressive strengths exceeding 100 megapascals.', $lyceon_json$[{"key":"A","text":"The thermal insulation capacity and the mechanical fragility of silica aerogels are both consequences of the same underlying structural characteristic, making it difficult to improve one without compromising the other."},{"key":"B","text":"Polymer-crosslinked aerogels have entirely resolved the tradeoff between insulation and durability by achieving both properties at levels superior to those of traditional silica aerogels."},{"key":"C","text":"The fragility of silica aerogels is an unrelated manufacturing defect that researchers expect to eliminate without affecting the material's thermal insulation performance."},{"key":"D","text":"Silica aerogels are primarily valued for their compressive strength in construction applications, with their thermal insulation capacity considered a secondary and less commercially important property."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that "extreme porosity" gives aerogels both extraordinary insulation and exceptional fragility, and that polymer-crosslinked aerogels must "sacrifice a portion of insulation performance" to gain strength. This indicates both properties stem from the same structural feature (porosity), creating an inherent tradeoff. The option claiming the tradeoff has been entirely resolved misreads the passage, which explicitly states that crosslinked aerogels accept 40% higher thermal conductivity — a significant compromise, not an elimination of the tradeoff. The option describing fragility as an unrelated manufacturing defect contradicts the passage''s causal explanation linking both properties to porosity. The option about aerogels being primarily valued for compressive strength in construction directly contradicts the passage, which highlights their extremely low compressive strength (0.3 megapascals) and emphasizes their insulation as the extraordinary property.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RTURUA', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason certain deep-sea organisms have proven difficult to study using conventional oceanographic methods?', E'The following passage is adapted from a 2022 article in Marine Biology Review. Hadal trenches, oceanic depressions exceeding 6,000 meters in depth, harbor ecosystems whose inhabitants have long eluded systematic observation. Conventional remotely operated vehicles (ROVs) designed for continental shelf research typically withstand pressures up to 600 atmospheres, whereas the deepest hadal environments subject equipment to pressures surpassing 1,100 atmospheres. Moreover, the narrow, steeply walled geometry of these trenches complicates the deployment of standard trawling nets, which require broad, relatively flat terrain to function effectively. As a result, much of what scientists know about hadal fauna derives from baited camera traps rather than direct specimen collection.', $lyceon_json$[{"key":"A","text":"Hadal organisms are too small to be captured by conventional trawling nets, requiring specialized micro-collection devices instead."},{"key":"B","text":"The extreme pressures and narrow physical geometry of hadal trenches exceed the operational limits of standard deep-sea research equipment."},{"key":"C","text":"Scientists have historically prioritized continental shelf ecosystems, leaving hadal trench research chronically underfunded and understaffed."},{"key":"D","text":"Baited camera traps have replaced ROVs entirely because camera technology provides higher-resolution imagery of hadal fauna at extreme depths."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage identifies two specific obstacles: ROVs cannot withstand pressures above 600 atmospheres when hadal environments exceed 1,100, and the steep, narrow trench geometry prevents standard trawling nets from functioning. The option citing extreme pressures and narrow geometry accurately synthesizes both stated reasons. The option about organisms being too small for nets misreads the passage, which attributes the trawling difficulty to terrain shape, not organism size. The option about chronic underfunding infers a cause the passage never mentions; the text attributes the difficulty to equipment limitations, not resource allocation. The option claiming camera traps have entirely replaced ROVs overstates the passage, which says camera traps are the primary source of knowledge but does not say ROVs have been abandoned altogether.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T2JTLI', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U89QA9', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the function of the discussion of Harappan standardized weights in the overall structure of the text?', E'The following passage is adapted from a 2021 article in the Journal of Archaeological Theory. Scholars have long debated whether the Harappan civilization of the Indus Valley (c. 2600–1900 BCE) operated under centralized political authority. Proponents of centralization point to the uniformity of Harappan urban planning: streets in Mohenjo-daro and Harappa follow rigid grid patterns, and brick dimensions conform to a consistent 1:2:4 ratio across settlements separated by hundreds of kilometers. Skeptics counter that such architectural regularity could emerge from shared craft traditions rather than top-down decree. The discovery of standardized cubical weights, however, has shifted the discourse. These weights, found at sites from coastal Gujarat to the upper Punjab, follow an invariant ratio system based on a unit of approximately 13.7 grams, suggesting a degree of administrative coordination that craft convention alone would struggle to explain.', $lyceon_json$[{"key":"A","text":"It undermines the skeptics' argument that Harappan architectural uniformity could be explained by decentralized craft traditions alone."},{"key":"B","text":"It introduces a new line of evidence that the author presents as more difficult to attribute to informal cultural transmission than architectural uniformity is."},{"key":"C","text":"It provides conclusive proof that the Harappan civilization maintained a bureaucratic administration comparable to contemporary Mesopotamian states."},{"key":"D","text":"It illustrates how archaeological discoveries frequently overturn established scholarly consensus about the political organization of ancient civilizations."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents standardized weights as evidence that "shifted the discourse" because their invariant ratio system across distant sites is harder to explain through craft convention alone than architectural patterns are. The option describing the weights as a new line of evidence more difficult to attribute to informal cultural transmission accurately captures this structural function. The option about undermining the skeptics'' argument captures only part of the logic; the passage does not say the weights fully undermine the skeptics but rather that they are harder for the craft-convention explanation to account for, which is a subtler point about relative evidential weight. The option claiming conclusive proof overstates the passage, which uses the hedging phrase "suggesting a degree of" rather than asserting certainty. The option about archaeological discoveries frequently overturning consensus generalizes far beyond what the passage discusses, which is limited to one specific debate about one civilization.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UQNZ5K', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2023 study published in the journal Antiquity, archaeologist Drs. Hwan-Soo Cho and Yael Mendez analyzed ceramic fragments unearthed at a Neolithic settlement in southern Turkey. The fragments bore geometric motifs strikingly similar to those found on pottery from contemporaneous sites in the Caucasus region, over 600 miles to the northeast. ______ Cho and Mendez caution that the resemblance might reflect independent invention rather than direct contact, since both cultures relied on the same locally available pigments and firing techniques.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first two sentences describe a finding of striking similarity between ceramics from distant sites, which implies possible contact between cultures. The final sentence then introduces a counterpoint: the researchers caution that the similarity could be coincidental. "Nevertheless," correctly signals this concessive shift. "Moreover," incorrectly signals an addition that builds on the previous point, but the final sentence qualifies rather than extends it. "Specifically," incorrectly signals elaboration or detail, but the final sentence introduces a contrasting interpretation rather than specifying the earlier claim. "Similarly," incorrectly implies that the final sentence echoes a parallel pattern, when it actually introduces a competing explanation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V6UIGT', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'The following passage is from a 2023 article about urban beekeeping in Montreal. Unlike rural honeybee colonies, which forage across vast expanses of farmland, urban colonies in Montreal navigate a patchwork of rooftop gardens, public parks, and residential flower beds. A study conducted by entomologists at McGill University found that urban bees in the city produced honey with a more varied mineral profile than their rural counterparts, likely because they drew nectar from a wider diversity of ornamental and native plant species within a compact foraging radius of approximately 1.7 kilometers.', $lyceon_json$[{"key":"A","text":"Urban honeybees in Montreal produce honey with a more diverse mineral composition than rural honeybees, probably because of the variety of plants available in cities."},{"key":"B","text":"Entomologists at McGill University have begun a long-term research program to compare the health outcomes of urban and rural honeybee colonies across several Canadian provinces."},{"key":"C","text":"Rooftop gardens in Montreal are specifically designed to support pollinator populations by including native flowering species that bloom throughout the growing season."},{"key":"D","text":"Rural honeybee colonies are at a disadvantage compared to urban colonies because farmland offers fewer types of flowering plants for foraging purposes."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage focuses on the finding that urban bees in Montreal produce honey with a more varied mineral profile due to the diversity of plants within their compact foraging range. The option stating that urban honeybees produce honey with a more diverse mineral composition because of plant variety accurately captures this main idea. The option about McGill entomologists beginning a long-term multi-province research program misreads the passage, which describes a single study in Montreal, not an ongoing program across provinces. The option about rooftop gardens being specifically designed to support pollinators introduces a claim not present in the passage, which merely lists rooftop gardens as part of the urban landscape. The option claiming rural colonies are at a disadvantage distorts the passage''s comparison; the text notes a difference in honey composition but does not characterize rural colonies as disadvantaged.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W36CT9', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively illustrate the claim made in the text about Okri''s narrative technique?', E'The following passage is from a 2020 essay on contemporary African fiction. Ben Okri''s novels frequently blur the boundary between the tangible and the spectral, situating characters in landscapes where ancestral spirits interact with the living as though occupying the same physical plane. Critics have noted that this technique does not function as allegory or metaphor; rather, Okri treats the coexistence of the material and the spiritual as a literal condition of his fictional worlds, one that characters navigate with the same practical attention they give to hunger or weather.', $lyceon_json$[{"key":"A","text":"\"Okri's prose style draws heavily on the oral storytelling traditions of the Yoruba, employing cyclical narrative structures and call-and-response rhythmic patterns that echo communal performance.\""},{"key":"B","text":"\"In Okri's fiction, ghosts do not symbolize anything beyond themselves; they are neighbors, obstacles, companions — as mundane and consequential as a blocked road or a failed harvest.\""},{"key":"C","text":"\"Okri's political commentary is embedded so deeply in his symbolism that readers must decode each supernatural event as a stand-in for a specific historical injustice in postcolonial Nigeria.\""},{"key":"D","text":"\"What distinguishes Okri from other magical realist writers is his insistence on anchoring every fantastical element to a verifiable detail of Nigerian geography and material culture.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The passage claims Okri treats the coexistence of material and spiritual as a literal condition, not allegory, and that characters navigate spiritual beings with practical attention. The quotation describing ghosts as neighbors, obstacles, and companions who are as mundane as a blocked road or failed harvest directly illustrates this literalness. The quotation about Yoruba oral traditions and cyclical narrative structures addresses style and form, not the specific claim about treating the spiritual as literal. The quotation about decoding supernatural events as stand-ins for historical injustice directly contradicts the passage''s assertion that Okri''s technique is not allegorical or metaphorical. The quotation about anchoring fantastical elements to verifiable Nigerian geography describes a different technique — geographical realism — rather than the passage''s point about spiritual beings being treated as literal presences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WF3C14', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about the architect Lina Bo Bardi''s approach to museum design?', E'The following passage is from a 2021 monograph on Brazilian modernist architecture. When Lina Bo Bardi designed the Sao Paulo Museum of Art in 1968, she suspended the main exhibition hall on two massive concrete beams, leaving the ground level entirely open as a public plaza. Unlike contemporaries who enclosed museum lobbies behind glass walls and turnstiles, Bo Bardi insisted that pedestrians should pass freely beneath the building without purchasing a ticket or even realizing they had entered a cultural institution. She described the open ground floor as a "civic living room" that belonged to the city rather than to the museum''s administration.', $lyceon_json$[{"key":"A","text":"She believed that museums should be physically accessible to the general public, not separated from everyday urban life by barriers."},{"key":"B","text":"She rejected modernist construction techniques in favor of traditional Brazilian building methods that emphasized natural materials over concrete."},{"key":"C","text":"She prioritized the aesthetic impact of the building's exterior over the practical needs of exhibiting and preserving artwork inside the museum."},{"key":"D","text":"She intended the open plaza to serve primarily as a commercial space where local vendors could sell goods to museum visitors and passersby."}]$lyceon_json$::jsonb, 'A', NULL, E'Bo Bardi left the ground floor open so pedestrians could pass freely without tickets or even awareness of entering a cultural space, and she called it a "civic living room" belonging to the city. This directly supports the inference that she believed museums should be accessible and integrated into urban life rather than separated by barriers. The option about rejecting modernist techniques contradicts the passage, which describes her using massive concrete beams — a quintessentially modernist method. The option about prioritizing exterior aesthetics over practical exhibition needs goes beyond the text, which discusses accessibility philosophy rather than any tension between aesthetics and functionality. The option about commercial vendor space introduces a purpose the passage never mentions; Bo Bardi''s description of a "civic living room" implies public gathering, not commerce.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WQSKIF', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a comparative analysis of two conservation strategies and wants to highlight a point of agreement between the researchers despite their differing overall approaches. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XWYBDN', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YJRI32', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "arrested" most nearly means', E'Writing in a 2021 monograph on urban ecology, landscape architect Priya Vasudeva argued that the proliferation of impervious surfaces in metropolitan cores has <u>arrested</u> the natural succession of riparian plant communities along channelized waterways. Without periodic flooding and soil deposition, she noted, the pioneer species that would ordinarily give way to hardwood canopy remain fixed in a perpetual early stage.', $lyceon_json$[{"key":"A","text":"halted"},{"key":"B","text":"detained"},{"key":"C","text":"captivated"},{"key":"D","text":"accelerated beyond recovery"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that plant communities remain fixed in a perpetual early stage, meaning their natural progression has been stopped. "Halted" precisely captures this sense of an interrupted process. "Detained" applies the law-enforcement sense of arrest, which involves holding a person, not stopping a biological process. "Captivated" applies another meaning of arrest — seizing attention — which is incoherent when applied to ecological succession. "Accelerated beyond recovery" introduces a meaning opposite to what the passage describes; the succession was stopped, not sped up.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZAJGJZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about why the Alvarez team''s hypothesis was initially met with resistance from some paleontologists?', E'The following passage is from a 2022 history of science article. In 1980, physicist Luis Alvarez and his son Walter, a geologist, proposed that a massive asteroid impact caused the mass extinction event at the end of the Cretaceous period, approximately 66 million years ago. Their evidence centered on an anomalous concentration of iridium — an element rare in Earth''s crust but abundant in extraterrestrial bodies — found in a thin clay layer at the Cretaceous-Paleogene boundary worldwide. Many paleontologists, however, had spent decades developing gradualist models attributing the extinction to prolonged volcanic activity in the Deccan Traps of present-day India, which released enormous quantities of sulfur dioxide and carbon dioxide over several hundred thousand years. These researchers argued that the fossil record showed species declining well before any single catastrophic event.', $lyceon_json$[{"key":"A","text":"The Alvarez team lacked the geological credentials typically expected of researchers proposing theories about mass extinction events in Earth's deep past."},{"key":"B","text":"Many paleontologists had invested significant professional effort in alternative explanations that attributed the extinction to gradual environmental processes rather than a single sudden event."},{"key":"C","text":"The iridium evidence was quickly shown to be unreliable because similar concentrations had been found in geological layers unrelated to any known extinction event."},{"key":"D","text":"Luis Alvarez had previously published several controversial physics papers that had been retracted, undermining his credibility in the broader scientific community."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that many paleontologists had "spent decades developing gradualist models" based on volcanic activity and that they argued the fossil record showed species declining before any single catastrophe. This directly supports the inference that resistance stemmed from professional investment in gradual-process explanations. The option about lacking geological credentials introduces a claim the passage does not make; while Luis Alvarez was a physicist, the passage does not suggest credentials were the basis of resistance. The option about iridium evidence being shown unreliable misreads the passage, which presents the iridium anomaly as the Alvarez team''s key evidence without indicating it was discredited. The option about retracted physics papers fabricates biographical details entirely absent from the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZIAZP4', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster has served as a model organism in genetics research for over a century. <u>In 1910, Thomas Hunt Morgan observed a white-eyed male fly among his red-eyed specimens, a mutation that proved instrumental in establishing the chromosomal theory of inheritance.</u> Since Morgan''s discovery, thousands of genetic studies have relied on Drosophila to elucidate fundamental principles of heredity and development.', $lyceon_json$[{"key":"A","text":"It provides a specific historical example that illustrates the broader claim made in the preceding sentence."},{"key":"B","text":"It introduces a controversy about the reliability of early genetics experiments."},{"key":"C","text":"It transitions from a discussion of Drosophila anatomy to an analysis of modern breeding programs."},{"key":"D","text":"It challenges the assumption that model organisms are necessary for productive genetic research."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence claims Drosophila has served as a model organism for over a century, and the underlined sentence offers Morgan''s 1910 discovery as concrete evidence of that long history. Providing a specific historical example that illustrates the broader claim accurately describes this function. The option claiming a controversy is introduced misidentifies the tone; the passage presents Morgan''s work as a celebrated milestone, not a contested finding. The option about transitioning from anatomy to breeding programs misreads both the subject matter before and after the underlined sentence. The option about challenging the necessity of model organisms inverts the passage''s logic, which affirms their usefulness.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
